// Shared service — no version coupling
public interface IUserService
{
    Task<UserResponse> GetAsync(Guid id);
}

// v1 controller
[ApiController]
[Route("v{version:apiVersion}/users")]
[ApiVersion("1.0")]
public class UsersV1Controller : ControllerBase
{
    private readonly IUserService _service;
    public UsersV1Controller(IUserService service) => _service = service;

    [HttpGet("{id}")]
    public async Task<ActionResult<UserResponseV1>> Get(Guid id)
    {
        var user = await _service.GetAsync(id);
        return Ok(new UserResponseV1
        {
            Id = user.Id,
            Username = user.Username,
            Email = user.Email
        });
    }
}

// v2 controller — adds displayName
[ApiController]
[Route("v{version:apiVersion}/users")]
[ApiVersion("2.0")]
public class UsersV2Controller : ControllerBase
{
    private readonly IUserService _service;
    public UsersV2Controller(IUserService service) => _service = service;

    [HttpGet("{id}")]
    public async Task<ActionResult<UserResponseV2>> Get(Guid id)
    {
        var user = await _service.GetAsync(id);
        return Ok(new UserResponseV2
        {
            Id = user.Id,
            Username = user.Username,
            Email = user.Email,
            DisplayName = user.DisplayName,  // New in v2
            AvatarUrl = user.AvatarUrl       // New in v2
        });
    }
}

